import pandas as pd

def clean(df):
    df = df.copy()
    # normalize text columns: strip whitespace
    for col in ['sex', 'island', 'species']:
        if col in df.columns:
            df[col] = df[col].where(df[col].isna(), df[col].astype(str).str.strip())
    # sex: lower case and strip, empty -> NA
    if 'sex' in df.columns:
        df['sex'] = df['sex'].where(df['sex'].isna(), df['sex'].astype(str).str.strip().str.lower())
        df.loc[df['sex'] == '', 'sex'] = pd.NA
        # keep only allowed values, others become NA (do not guess)
        allowed_sex = {'male', 'female'}
        df.loc[~df['sex'].isin(allowed_sex) & df['sex'].notna(), 'sex'] = pd.NA
    # island variant Bisco -> Biscoe
    if 'island' in df.columns:
        df['island'] = df['island'].replace({'Bisco': 'Biscoe'})
    # convert numeric columns that may be stored as text
    for col in ['body_mass_g', 'flipper_length_mm', 'bill_length_mm', 'bill_depth_mm', 'year']:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')
    # drop exact duplicate rows
    df = df.drop_duplicates()
    return df

def answer(df):
    df = clean(df)
    if 'body_mass_g' in df.columns:
        df['body_mass_g'] = pd.to_numeric(df['body_mass_g'], errors='coerce')
    # drop missing group keys (sex unknown)
    df = df.dropna(subset=['sex'])
    if df.empty:
        return {}
    grouped = df.groupby('sex', dropna=True)['body_mass_g'].mean()
    # build dict, drop missing keys, ensure string keys
    out = {}
    for k, v in grouped.items():
        if pd.isna(k) or pd.isna(v):
            continue
        out[str(k)] = float(v)
    return out
